#include <stdio.h>
#include <stdlib.h>

// Pointeur sur fonction
int comparer_asc(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

int comparer_desc(const void *a, const void *b) {
    return (*(int*)b - *(int*)a);
}

int main() {
    int tab[] = {5, 2, 8, 1, 9, 3};
    int n = 6;

    // qsort prend un pointeur sur fonction
    qsort(tab, n, sizeof(int), comparer_asc);
    for (int i = 0; i < n; i++) printf("%d ", tab[i]);
    printf("\n"); // 1 2 3 5 8 9

    qsort(tab, n, sizeof(int), comparer_desc);
    for (int i = 0; i < n; i++) printf("%d ", tab[i]);
    printf("\n"); // 9 8 5 3 2 1
    return 0;
}
